import React, { useState, useEffect, useCallback } from "react";
import axios from "axios";
import styled from "styled-components";
import { useParams } from "react-router-dom";

const EmployeePage = () => {
  const { id } = useParams(); // Lorry ID
  const [employeeName, setEmployeeName] = useState("");
  const [employeePhone, setEmployeePhone] = useState("");
  const [employeeRole, setEmployeeRole] = useState("driver");
  const [employeeSalary, setEmployeeSalary] = useState("");
  const [filteredEmployees, setFilteredEmployees] = useState([]);
  const [isEmployeeFormVisible, setEmployeeFormVisible] = useState(false);
  const [selectedEmployee, setSelectedEmployee] = useState(null);
  const [salaryDetails, setSalaryDetails] = useState(null);
  const [salaryFormVisible, setSalaryFormVisible] = useState(false);
  const [daysWorked, setDaysWorked] = useState("");
  const [expense, setExpense] = useState("");

  const fetchEmployeesByRole = useCallback(async (role) => {
    try {
      const response = await axios.get(
        `http://localhost:5001/api/employee/employeesByRole/${id}/${role}`
      );
      setFilteredEmployees(response.data);
    } catch (error) {
      console.error("Error fetching employees:", error);
    }
  }, [id]);

  const addEmployee = async () => {
    try {
      const newEmployee = {
        name: employeeName,
        phone: employeePhone,
        role: employeeRole,
        fixed_salary: employeeSalary,
        lorry_id: id,
      };
      await axios.post("http://localhost:5001/api/employee/add", newEmployee);
      alert("Employee added successfully");
      fetchEmployeesByRole(employeeRole);
      setEmployeeFormVisible(false);
    } catch (error) {
      console.error("Error adding employee:", error);
      alert("Error adding employee");
    }
  };

  const handleEmployeeClick = async (employee) => {
    setSelectedEmployee(employee);
    setSalaryFormVisible(true); // Show salary form for the selected employee
  };

  // Handle Salary Form Submit
  const handleSalaryAdd = async () => {
    if (!daysWorked || !expense) {
      alert("Please enter all salary details.");
      return;
    }

    const salaryPerDay = selectedEmployee.fixed_salary / 30;
    const currentMonth = new Date().getMonth() + 1;
    const currentYear = new Date().getFullYear();

    try {
      await axios.post("http://localhost:5001/api/employeeSalary/add", {
        employee_id: selectedEmployee.id,
        month: currentMonth,
        year: currentYear,
        salary_per_day: salaryPerDay,
        days_worked: daysWorked,
        expense: expense,
      });
      alert("Salary details added successfully");
      setSalaryFormVisible(false); // Hide salary form
    } catch (error) {
      console.error("Error adding salary details:", error);
      alert("Error adding salary details");
    }
  };

  useEffect(() => {
    fetchEmployeesByRole(employeeRole);
  }, [employeeRole, id]);

  return (
    <Container>
      <Header>
        <LorryTitle>Lorry {id}</LorryTitle>
      </Header>

      <Button onClick={() => setEmployeeFormVisible(!isEmployeeFormVisible)}>
        {isEmployeeFormVisible ? "Cancel" : "Add Employee"}
      </Button>

      {isEmployeeFormVisible && (
        <Form>
          <Input
            type="text"
            placeholder="Employee Name"
            value={employeeName}
            onChange={(e) => setEmployeeName(e.target.value)}
          />
          <Input
            type="text"
            placeholder="Phone Number"
            value={employeePhone}
            onChange={(e) => setEmployeePhone(e.target.value)}
          />
          <Select
            value={employeeRole}
            onChange={(e) => setEmployeeRole(e.target.value)}
          >
            <option value="driver">Driver</option>
            <option value="driller">Driller</option>
            <option value="manager">Manager</option>
            <option value="worker">Worker</option>
          </Select>
          <Input
            type="number"
            placeholder="Fixed Salary"
            value={employeeSalary}
            onChange={(e) => setEmployeeSalary(e.target.value)}
          />
          <Button onClick={addEmployee}>Add Employee</Button>
        </Form>
      )}

      {/* Employee List */}
      <EmployeeList>
        {filteredEmployees.length > 0 ? (
          filteredEmployees.map((employee) => (
            <EmployeeItem
              key={`${employee.id}-${employee.phone}`}
              onClick={() => handleEmployeeClick(employee)}
            >
              {employee.name} ({employee.phone})
            </EmployeeItem>
          ))
        ) : (
          <EmployeeItem>No employees found for this role.</EmployeeItem>
        )}
      </EmployeeList>

      {/* Salary Details Form for Selected Employee */}
      {salaryFormVisible && selectedEmployee && (
        <SalaryForm>
          <h3>{selectedEmployee.name} Salary Details</h3>
          <Input
            type="number"
            placeholder="Days Worked"
            value={daysWorked}
            onChange={(e) => setDaysWorked(e.target.value)}
          />
          <Input
            type="number"
            placeholder="Expense"
            value={expense}
            onChange={(e) => setExpense(e.target.value)}
          />
          <Button onClick={handleSalaryAdd}>Add Salary Details</Button>
        </SalaryForm>
      )}
    </Container>
  );
};

export default EmployeePage;

// Styled Components
const Container = styled.div`
  padding: 20px;
  background-color: #f4f7fc;
`;

const Header = styled.header`
  display: flex;
  justify-content: center;
  padding: 20px;
  background-color: #ffffff;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
`;

const LorryTitle = styled.h1`
  font-size: 2rem;
  font-weight: bold;
`;

const Button = styled.button`
  padding: 10px 20px;
  background-color: #4caf50;
  color: white;
  font-size: 1.1rem;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  margin-top: 20px;

  &:hover {
    background-color: #45a049;
  }
`;

const Form = styled.div`
  background-color: #ffffff;
  padding: 20px;
  margin-top: 20px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
`;

const Input = styled.input`
  width: 100%;
  padding: 10px;
  margin: 10px 0;
  border: 1px solid #ccc;
  border-radius: 5px;
`;

const Select = styled.select`
  width: 100%;
  padding: 10px;
  margin: 10px 0;
  border: 1px solid #ccc;
  border-radius: 5px;
`;

const EmployeeList = styled.ul`
  list-style-type: none;
  padding: 0;
`;

const EmployeeItem = styled.li`
  font-size: 1rem;
  padding: 5px;
  border-bottom: 1px solid #ccc;
  cursor: pointer;

  &:hover {
    background-color: #f4f4f9;
  }
`;

const SalaryForm = styled.div`
  background-color: #ffffff;
  padding: 20px;
  margin-top: 20px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
`;
